 const string E=PlazaKeynesAuthoring.Evidence,Key="PlazaKeynes.Play";static IEnumerator routine;static Stack<IEnumerator> stack=new Stack<IEnumerator>();static int lastFrame;static double deadline;static List<string> checks=new List<string>(),errors=new List<string>(),warnings=new List<string>();static List<View> views=new List<View>();static List<double> frameMs=new List<double>();static PlayerController player;static PlayerMovement movement;static PlayerCameraController cameraController;static PlayerInputReader reader;static Keyboard keyboard;static int oldCapture;static bool oldBackground;static InputSettings.BackgroundBehavior oldInputBackground;static InputSettings.EditorInputBehaviorInPlayMode oldEditorInput;static double previousTime;static string sourceSceneHash;static bool measuring,sceneChecksCompleted;static Dictionary<string,Vector3> positions;
