 public static void Begin(){sourceSceneHash=Hash(PlazaKeynesAuthoring.ScenePath);SessionState.SetString(Key+"Hash",sourceSceneHash);PlayerSettings.productName="PlazaKeynes_Validation_20261024";SessionState.SetBool(Key,true);startAt=EditorApplication.timeSinceStartup+12;EditorApplication.update+=StartReady;}
