 static void State(PlayModeStateChange s){if(!SessionState.GetBool(Key,false))return;if(s==PlayModeStateChange.EnteredPlayMode){oldCapture=Time.captureFramerate;oldBackground=Application.runInBackground;oldInputBackground=InputSystem.settings.backgroundBehavior;oldEditorInput=InputSystem.settings.editorInputBehaviorInPlayMode;Time.captureFramerate=30;Application.runInBackground=true;InputSystem.settings.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;InputSystem.settings.editorInputBehaviorInPlayMode=InputSettings.EditorInputBehaviorInPlayMode.AllDeviceInputAlwaysGoesToGameView;Application.logMessageReceived+=Log;deadline=EditorApplication.timeSinceStartup+720;lastFrame=-1;routine=Tests();stack.Clear();stack.Push(routine);}if(s==PlayModeStateChange.EnteredEditMode){SessionState.SetBool(Key,false);bool unchanged=Hash(PlazaKeynesAuthoring.ScenePath)==SessionState.GetString(Key+"Hash","");var sorted=frameMs.OrderBy(v=>v).ToArray();var result=new Result{passed=checks.Count>20&&errors.Count==0,realPlayMode=true,sceneChecksCompleted=sceneChecksCompleted,sceneFunctionalPassed=sceneChecksCompleted&&!errors.Any(e=>!e.Contains("UnityEditor.Search.SearchDatabase")),sceneUnchanged=unchanged,scene=PlazaKeynesAuthoring.ScenePath,graphicsDevice=SystemInfo.graphicsDeviceName,scope="Only new Level02. Real existing PlayerController/InputSystem keyboard simulation; controlled route starts and FPS/TPS modes. No global regressions, new gameplay, catalog/menu wiring or human free-navigation certification. Frame times are Editor process observations, not integrated-GPU build certification; UnityStats are raw Editor counters.",checks=checks.ToArray(),errors=errors.ToArray(),warnings=warnings.Distinct().ToArray(),sampleFrames=sorted.Length,meanEditorFrameMs=sorted.Length>0?sorted.Average():0,p95EditorFrameMs=sorted.Length>0?sorted[(int)Math.Ceiling(sorted.Length*.95)-1]:0,views=views.ToArray()};File.WriteAllText(E+"/Play_Validation.json",JsonUtility.ToJson(result,true));Edit