 static void Poll(){if(!SessionState.GetBool(Key,false)||!EditorApplication.isPlaying||routine==null||lastFrame==Time.frameCount)return;lastFrame=Time.frameCount;EditorApplication.QueuePlayerLoopUpdate();try{if(EditorApplication.timeSinceStartup>deadline)throw new Exception("Level02-only validation timeout");if(measuring){double now=Time.realtimeSinceStartupAsDouble;if(previousTime>0)frameMs.Add((now-previousTime)*1000);previousTime=now;}while(stack.Count>0){var top=stack.Peek();if(!top.MoveNext()){stack.Pop();continue;}if(top.Current is IEnumerator nested){stack.Push(nested);continue;}return;}routine=null;Finish();}catch(Exception e){errors.Add(e.ToString());routine=null;Finish();}}
 static void Send(bool walk){InputSystem.QueueStateEvent(keyboard,walk?new KeyboardState(UnityEngine.InputSystem.Key.W):new KeyboardState());InputSystem.Update();}
 static void Teleport(Vector3 p,float yaw){var cc=player.GetComponent<CharacterController>();cc.enabled=false;player.transform.position=p;player.transform.rotation=Quaternion.Euler(0,yaw,0);cc.enabled=true;movement.StopMotion();player.GetComponent<PlayerLook>().SynchronizePlayerYaw();cameraController.SnapAfterTeleport();Physics.SyncTransforms();}
 static IEnumerator Walk(Vector3 start,float yaw,CameraMode mode,int frames,string label,float minimum){cameraController.ApplyCameraMode(mode);Teleport(start,yaw);for(int n=0;n<10;n++){Send(false);yield return null;}var before=player.transform.position;for(int n=0;n<frames;n++){Send(true);yield return null;Check(player.transform.position.y>-.3f,label+" ground retained "+n);}Send(false);yield return null;var after=player.transform.position;Check(Vector3.Distance(new Vector3(before.x,0,before.z),new Vector3(after.x,0,after.z))>minimum,label+" advances without major blocker");Check(cameraController.Mode==mode,label+" camera mode remains correct");if(mode==CameraMode.ThirdPerson){Check(Vector3.Distance(Camera.main.transform.position,player.transform.position)>1,"TPS maintains useful orbit distance");Capture("PlazaKeynes_TPSExploration",null,null,true);}}
 static IEnumerator Tests(){for(int i=0;i<40;i++)yield return null;player=UnityEngine.Object.FindAnyObjectByType<PlayerController>();movement=player.GetComponent<PlayerMovement>();cameraController=player.GetComponent<PlayerCameraController>();reader=player.GetComponent<PlayerInputReader>();Check(player&&movement&&reader&&cameraController.IsConfigured,"Existing configured Explorer player system");Check(UnityEngine.Object.FindObjectsByType<PlayerController>(FindObjectsInactive.Include).Length==1,"No duplicate Player");Check(UnityEngine.Object.FindObjectsByType<Camera>(FindObjectsInactive.Include).Count(c=>c.CompareTag("MainCamera"))==1,"No duplicate MainCamera");Check(UnityEngine.Object.FindObjectsByType<AudioListener>(FindObjectsInactive.Include).Count()==1,"No duplicate AudioListener");Check(UnityEngine.Object.FindObjectsByType<MonoBehaviour>(FindObjectsInactive.Include).Count(c=>c.GetType().Name=="EventSystem")<=1,"No duplicate EventSystem");Check(Vector3.Distance(player.transform.position,new Vector3(0,0,-72))<.5f,"New scene spawn at arrival, ground supported");Check(player.GameplayActive&&reader.GameplayEnabled,"Existing movement/input enabled without new gameplay");var env=GameObject.Find("ENV_Level02_PlazaKeynes");var bg=env.transform.Find("Background_Jungle");Check(bg.GetComponentsInChildren<Collider>(true).All(c=>!c.enabled),"Background has no enabled colliders");Check(env.transform.Find("Vegetation_Low").GetComponentsInChildren<Collider>(true).All(c=>!c.enabled),"Small vegetation has no enabled colliders");Check(env.GetComponentsInChildren<LODGroup>().Length>300,"LOD groups active and background simplified");Check(UnityEngine.Object.FindObjectsByType<Light>().Count(l=>l.type==LightType.Directional)==1,"One directional daylight, no volumetric lighting");Check(!UnityEngine.Object.FindObjectsByType<MonoBehaviour>().Any(m=>m.GetType().Namespace!=null&&m.GetType().Namespace.StartsWith("Tikal.Puzzles")),"No puzzles/Clue gameplay in Level02");
 keyboard=InputSystem.AddDevice<Keyboard>();reader.InteractAction.actionMap.asset.devices=new InputDevice[]{keyboard};player.SetGameplayActive(true);
 Capture("PlazaKeynes_Entrance",new Vector3(0,2,-73),new Vector3(0,5,0));Capture("PlazaKeynes_Center",new Vector3(-23,3,-26),new Vector3(0,5,0));Capture("PlazaKeynes_StatueFront",new Vector3(-6,4,-16),new Vector3(0,5.3f,0));Capture("PlazaKeynes_StatueWide",new Vector3(34,13,-47),new Vector3(0,5,0));Capture("PlazaKeynes_LeftSector",new Vector3(-25,7,-52),new Vector3(-80,13,45));Capture("PlazaKeynes_RightSector",new Vector3(20,6,-52),new Vector3(100,15,67));Capture("PlazaKeynes_BackgroundTemples",new Vector3(0,32,-18),new Vector3(0,32,180));Capture("PlazaKeynes_Wide",new Vector3(-125,88,-135),new Vector3(0,8,20));
 yield return Walk(new Vector3(0,.1f,-72),0,CameraMode.FirstPerson,120,"FPS entrance path",10);yield return Walk(new Vector3(0,.1f,-41),0,CameraMode.ThirdPerson,90,"TPS arrival path",7);yield return Walk(new Vector3(-24,.1f,-18),0,CameraMode.FirstPerson,90,"West side of monument",7);yield return Walk(new Vector3(24,.1f,18),180,CameraMode.ThirdPerson,90,"East side of monument",7);yield return Walk(new Vector3(-18,.1f,24),90,CameraMode.FirstPerson,90,"North side of monument",7);yield return Walk(new Vector3(17,.1f,-24),270,CameraMode.FirstPerson,90,"South side of monument",7);
 yield return Walk(new Vector3(0,.1f,-13.5f),0,CameraMode.FirstPerson,65,"Central monument stair approach",4);Check(player.transform.position.y>.35f,"Central monument access actually climbed above plaza ground");
 var stair=env.transform.Find("Temples").GetComponentsInChildren<Transform>().First(t=>t.name=="StairCollisionProxy");yield return Walk(stair.position-stair.forward*.5f+Vector3.up*.1f,stair.eulerAngles.y,CameraMode.FirstPerson,90,"Left temple terrace stair",5);Check(player.transform.position.y>2,"Left temple first terrace ascent verified");
 cameraController.ApplyCameraMode(CameraMode.ThirdPerson);Teleport(new Vector3(16,.1f,-25),315);for(int i=0;i<20;i++)yield return null;Capture("PlazaKeynes_TPSExploration",null,null,true);Time.captureFramerate=0;measuring=true;previousTime=0;for(int i=0;i<120;i++)yield return null;measuring=false;Check(frameMs.Count>=100,"Editor frame observation sampled after warmup");Check(Physics.Raycast(player.transform.position+Vector3.up,Vector3.down,5,~0,QueryTriggerInteraction.Ignore),"Ground collider remains under player");sceneChecksCompleted=true;}
 static void Capture(string name,Vector3? position,Vector3? target,bool gameplay=false){var cam=Camera.main;var parent=cam.transform.parent;var p=cam.transform.localPosition;var q=cam.transform.localRotation;float f=cam.fieldOfView,aspect=cam.aspect;var rt=new RenderTexture(1600,900,24);rt.Create();var image=new Texture2D(1600,900,TextureFormat.RGB24,false);var prev=RenderTexture.active;try{cam.aspect=16f/9;if(position.HasValue){cam.transform.position=position.Value;cam.transform.LookAt(target.Value);cam.fieldOfView=62;}var request=new UniversalRenderPipeline.SingleCameraRequest{destination=rt};RenderPipeline.SubmitRenderRequest(cam,request);RenderPipeline.SubmitRenderRequest(cam,request);RenderTexture.active=rt;image.ReadPixels(new Rect(0,0,1600,900),0,0);image.Apply();Check(!image.GetPixels32().Any(c=>c.r>240&&c.b>240&&c.g<15),"No obvious magenta pixels in "+name);File.WriteAllBytes(E+"/Captures/"+name+".png",image.EncodeToPNG());views.Add(new View{name=name,rawEditorDrawCalls=UnityStats.drawCalls,rawEditorTriangles=UnityStats.triangles,camera=cam.transform.position,allocatedBytes=UnityEngine.Profiling.Profiler.GetTotalAllocatedMemoryLong()});}finally{cam.transform.SetParent(parent,false);cam.transform.localPosition=p;cam.transform.localRotation=q;cam.fieldOfView=f;cam.aspect=aspect;RenderTexture.active=prev;rt.Release();UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(image);}}
